/**
 * Escapes unescaped straight apostrophes inside single-quoted TypeScript
 * string values generated by the add-tool-content scripts.
 *
 * The generator functions embedded content like  supplier's  directly inside
 * 'VALUE',  without escaping, so TypeScript sees the apostrophe as the
 * closing quote.  This script fixes that by finding the last  ',  on each
 * affected line and escaping every bare  '  in the VALUE portion.
 */
import fs from 'node:fs';

const files = [
  'src/data/tools/invoice.ts',
  'src/data/tools/gst-invoice.ts',
  'src/data/tools/estimate.ts',
  'src/data/tools/proforma-invoice.ts',
  'src/data/tools/purchase-order.ts',
  'src/data/tools/delivery-challan.ts',
  'src/data/tools/payment-receipt.ts',
  'src/data/tools/credit-note.ts',
  'src/data/tools/debit-note.ts',
];

// Keys whose values may contain prose with apostrophes.
const KEY_RE = /^(\s+(?:q|a|text|detail|note|intro|heading|name|label): ')/;

// Inline refItem pattern: { label: '...', url: '...', note: 'VALUE' },
// The note value ends at the last  ' }
const INLINE_NOTE_RE = /(note: ')([^]*)(' },)/;

let totalFixes = 0;

for (const file of files) {
  let src = fs.readFileSync(file, 'utf8');
  const hasCRLF = src.includes('\r\n');
  if (hasCRLF) src = src.replace(/\r\n/g, '\n');

  const lines = src.split('\n');
  let fixes = 0;

  const fixedLines = lines.map(line => {
    // Pattern 1: line-start key  "      KEY: 'VALUE',"
    const km = line.match(KEY_RE);
    if (km) {
      const prefix   = km[1];
      const rest     = line.slice(prefix.length);
      const closeIdx = rest.lastIndexOf("',");
      if (closeIdx !== -1) {
        const value      = rest.slice(0, closeIdx);
        const suffix     = rest.slice(closeIdx);
        const fixedValue = value.replace(/(?<!\\)'/g, "\\'");
        if (fixedValue !== value) { fixes++; return prefix + fixedValue + suffix; }
      }
      return line;
    }
    // Pattern 2: inline refItem  "{ label: '...', url: '...', note: 'VALUE' },"
    if (INLINE_NOTE_RE.test(line)) {
      const fixed = line.replace(INLINE_NOTE_RE, (_, pre, val, suf) => {
        const fixedVal = val.replace(/(?<!\\)'/g, "\\'");
        if (fixedVal !== val) fixes++;
        return pre + fixedVal + suf;
      });
      return fixed;
    }
    return line;
  });

  src = fixedLines.join('\n');
  if (hasCRLF) src = src.replace(/\n/g, '\r\n');
  fs.writeFileSync(file, src);
  totalFixes += fixes;
  console.log(`${fixes > 0 ? 'fixed' : 'clean'} (${fixes} apostrophe(s)): ${file}`);
}
console.log(`\nTotal apostrophes escaped: ${totalFixes}`);
